import os

import shutil

import sys


def delete_files(file_paths):

    for file_path in file_paths:

        try:

            if os.path.isfile(file_path):

                os.remove(file_path)

                print(f"Deleted {file_path}")

            elif os.path.isdir(file_path):

                shutil.rmtree(file_path)

                print(f"Deleted directory {file_path}")

        except OSError as e:

            print(f"Error: {e.filename} - {e.strerror}")


if __name__ == "__main__":

    if len(sys.argv) > 1:

        delete_files(sys.argv[1:])

    else:

        print("Usage: python delete_files.py [file_path1] [file_path2] ...")

```

To use this script, save it as `delete_files.py` and run it from the command line, passing in the file or directory paths you want to delete. The script will delete all provided files and directories permanently. <|end|>
